REFERENCE_SOURCE = 'def precompute_xor_prefixes(values):\n    xor_prefixes = [0] * (len(values) + 1)\n    for i in range(len(values)):\n        xor_prefixes[i+1] = xor_prefixes[i] ^ values[i]\n    return xor_prefixes\n\n# 读取输入并处理\nvalues = list(map(int, input().split()))\nxor_prefixes = precompute_xor_prefixes(values)\n\n# 读取查询并处理\nfor _ in range(10000):\n    L, R = map(int, input().split())\n    result = xor_prefixes[R+1] ^ xor_prefixes[L]\n    print(result)\n'

def g20626(r):
    a=[r.randint(1,1000) for _ in range(r.randint(2,20))]; q=[]
    for _ in range(10000):
        l=r.randrange(len(a)); q.append(f"{l} {r.randint(l,len(a)-1)}")
    return " ".join(map(str,a))+"\n"+"\n".join(q)+"\n"

def valid(text):
    """题面契约：第一行是空格分隔的正整数数列 V（非空）；随后恰 10000 行，每行 "L R"，0<=L<=R<len(V)。
    注：题面样例只给 4 行查询，第 0 组按题面"10000 次查询"用 "0 0" 补齐，输出前 4 行即样例输出。"""
    if not text.endswith("\n"):
        return False
    lines = text[:-1].split("\n")
    if len(lines) != 10001:
        return False
    v = lines[0].split(" ")
    if not v or not all(t.isdigit() and t[0] != "0" for t in v):
        return False
    n = len(v)
    for line in lines[1:]:
        t = line.split(" ")
        if len(t) != 2 or not all(x.isdigit() and (x == "0" or x[0] != "0") for x in t):
            return False
        lo, hi = int(t[0]), int(t[1])
        if not 0 <= lo <= hi < n:
            return False
    return True


def extra_cases():
    """补充：n=1、n=2，以及 n=5e4 的大数列（卡每次查询 O(R-L) 的暴力；值到 2^30）。"""
    r = random.Random(NUMBER * 19 + 3)
    out = []

    def make(a, wide):
        q = []
        n = len(a)
        for _ in range(10000):
            if wide:
                lo = r.randrange(0, max(1, n // 10))
                hi = r.randrange(n - max(1, n // 10), n)
                lo = min(lo, hi)
            else:
                lo = r.randrange(n)
                hi = r.randint(lo, n - 1)
            q.append(f"{lo} {hi}")
        return " ".join(map(str, a)) + "\n" + "\n".join(q) + "\n"

    out.append(make([r.randint(1, 10 ** 9)], False))
    out.append(make([r.randint(1, 10 ** 9) for _ in range(2)], False))
    out.append(make([r.randint(1, 10 ** 9) for _ in range(50000)], True))
    out.append(make([r.randint(1, 2 ** 30) for _ in range(50000)], True))
    out.append(make([r.randint(1, 10 ** 9) for _ in range(50000)], False))
    return out


def build_cases():
    cases = [SAMPLE_IN]
    for i in range(1, 20):
        for attempt in range(100):
            value = g20626(random.Random(NUMBER + i + attempt * 1000))
            if value not in cases:
                cases.append(value)
                break
        else:
            raise AssertionError("生成器多样性不足")
    for value in extra_cases():
        if value not in cases:
            cases.append(value)
    for value in cases:
        assert valid(value), "生成的数据越出题面约束"
    return cases

def solve_reference(content):
    with tempfile.NamedTemporaryFile("w", suffix=".py", encoding="utf-8") as handle:
        handle.write(REFERENCE_SOURCE)
        handle.flush()
        result = subprocess.run(["python3", handle.name], input=content, text=True,
                                capture_output=True, timeout=120, check=True)
    return result.stdout


def main():
    cases = build_cases()
    assert cases[0] == SAMPLE_IN, "第 0 组必须是题面样例"
    assert solve_reference(SAMPLE_IN).split() == SAMPLE_OUT.split(), "参考解法跑不出样例输出"
    root = Path(__file__).parent / "data"
    root.mkdir(exist_ok=True)
    for index, content in enumerate(cases):
        (root / f"{index}.in").write_text(content, encoding="utf-8")
        (root / f"{index}.out").write_text(solve_reference(content), encoding="utf-8")


if __name__ == "__main__":
    main()
